INSERT INTO `datasets` VALUES (1,'Fabio Palomba; Dario Di Nucci; Michele Tufano; Gabriele Bavota; Rocco Oliveto; Denys Poshyvanyk; Andrea De Lucia','The Landfill main dataset realized for HIST (Historical Information for Smell deTection)','landfill','TSE dataset'),(2,'Fabio Palomba;Annibale Panichella;Andy Zaidman;Rocco Oliveto;Andrea De Lucia;','Previously built for Long Method, Blob, and Feature Envy, it has been enriched of two test smells, i.e. General Fixture and Eager Test. The dataset contains smells on 20 open source systems.','landfill','Code and Test Smell Dataset');
